class MonadicStateVerifier:
    """Verifies state transitions using the State Monad algebra.

    All state updates are encapsulated inside the monadic computation:
        S -> (A, S)
    No global (side-effectful) state is ever mutated, and the serialized
    coordinate is parsed with a safe parser instead of eval().
    """

    def parse(self, x: str):
        # Safe parsing: no instruction/data boundary collapse.
        # Accepts serialized tuples such as "(5, 10)".
        parsed = ast.literal_eval(x)
        if isinstance(parsed, (tuple, list)) and parsed:
            return parsed[0]
        if isinstance(parsed, (int, float)):
            return parsed
        raise ValueError(f"Unsupported serialized coordinate: {x!r}")

    def compute(self, x: str) -> StateMonad:
        val = self.parse(x)

        def transition(state):
            next_state = list(state)
            next_state.append(f"processed {val}")
            return (val + 1, next_state)

        return StateMonad(transition)

    def compute_bound(self, x: str) -> StateMonad:
        """Same transition expressed with the monad's bind operator."""
        val = self.parse(x)

        def log(_val):
            def transition(state):
                next_state = list(state)
                next_state.append(f"processed {val}")
                return (val + 1, next_state)
            return StateMonad(transition)

        return StateMonad.unit(val).bind(log)

