class ParseError(ValueError):
    """Raised when a serialized coordinate is malformed."""


class SandboxMonadicGuard:
    """Verifies serialized coordinates purely within the State Monad.

    Every state transition is modelled as S -> (A, S).  No global or
    otherwise mutable state is touched outside of the monadic computation,
    and untrusted input is never handed to eval().
    """

    @staticmethod
    def _parse(x: str):
        """Safely deserialize a coordinate tuple without eval()."""
        try:
            parsed = ast.literal_eval(x)
        except (ValueError, SyntaxError, MemoryError, RecursionError) as exc:
            raise ParseError(f"malformed coordinate: {x!r}") from exc
        if isinstance(parsed, tuple) and 1 <= len(parsed) <= 2:
            if all(isinstance(v, int) and not isinstance(v, bool) for v in parsed):
                return parsed[0]
        raise ParseError(f"malformed coordinate: {x!r}")

    def compute(self, x: str) -> StateMonad:
        # Build the transition lazily: nothing is executed (and no state is
        # read or written) until run_fn() is invoked by the caller.
        val = self._parse(x)

        def transition(state):
            next_state = list(state)
            next_state.append(f"processed {val}")
            return val + 1, next_state

        return StateMonad(transition)

