        # unchanged so that malformed or hostile input cannot crash the monad.
        result = val + 1 if isinstance(val, (int, float)) else val

        # The transition is captured *inside* the State Monad: the incoming
        # state is threaded through, a new state is derived, and both the value
        # and the new state are returned. Nothing outside is touched.
