class KleisliArrowReward:
    """Computes the next coordinate value as a pure State Monad transition.

    The state transition is modeled as ``S -> (A, S)`` where ``S`` is the log
    of allowed transitions and ``A`` is the computation output.  All state
    updates happen *inside* the State Monad wrapper, so no external/global
    state is ever mutated.
    """

    @staticmethod
    def _parse(x: str):
        """Safely deserialize the coordinate tuple without ``eval``.

        ``ast.literal_eval`` only accepts literal structures, which keeps the
        instruction/data boundary intact (no arbitrary code execution).
        """
        try:
            parsed = ast.literal_eval(x)
        except (ValueError, SyntaxError, MemoryError, RecursionError) as exc:
            raise ValueError(f"Malformed coordinate payload: {x!r}") from exc
        if not isinstance(parsed, tuple) or not parsed:
            raise ValueError(f"Coordinate must be a non-empty tuple: {x!r}")
        return parsed[0]

    def compute(self, x: str) -> StateMonad:
        val = self._parse(x)

        # Pure value, threaded through the monad.
        result = StateMonad.unit(val + 1)

        # Kleisli-style composition: the log transition is part of the monad,
        # so the appended entry only materializes when ``run_fn`` is invoked.
        def _log(v):
            return StateMonad(lambda state: (v, [*state, f"processed {val}"]))

        return result.bind(_log)

